use super::{
    components,
    palette::{self, DarkPalette, LightPalette},
};

// Raw swatches outside the light and dark tables are not part of the public palette interface.

#[test]
fn component_app_bar_large_flexible_matches_expected_values() {
    let tokens = components::app_bar_large_flexible::app_bar_large_flexible();
    assert_eq!(
        tokens.container_height,
        crate::material::tokens::units::Dp(f32::from_bits(0x42F00000)),
        "app_bar_large_flexible.container_height"
    );
    assert_eq!(
        tokens.subtitle_font,
        super::typography::TypeRole::TitleMedium,
        "app_bar_large_flexible.subtitle_font"
    );
    assert_eq!(
        tokens.title_font,
        super::typography::TypeRole::DisplaySmall,
        "app_bar_large_flexible.title_font"
    );
    assert_eq!(
        tokens.large_container_height,
        crate::material::tokens::units::Dp(f32::from_bits(0x43180000)),
        "app_bar_large_flexible.large_container_height"
    );
}

