#[test]
fn public_role_arrays_contain_every_variant_in_order() {
    use super::{
        color_role::ColorRole,
        foundation::{ElevationRole, StateRole},
        motion::{MotionRole, MotionScheme},
        shape::{CornerValueRole, ShapeRole},
    };

    assert_eq!(
        ColorRole::ALL,
        [
            ColorRole::Background,
            ColorRole::Error,
            ColorRole::ErrorContainer,
            ColorRole::InverseOnSurface,
            ColorRole::InversePrimary,
            ColorRole::InverseSurface,
            ColorRole::OnBackground,
            ColorRole::OnError,
            ColorRole::OnErrorContainer,
            ColorRole::OnPrimary,
            ColorRole::OnPrimaryContainer,
            ColorRole::OnPrimaryFixed,
            ColorRole::OnPrimaryFixedVariant,
            ColorRole::OnSecondary,
            ColorRole::OnSecondaryContainer,
            ColorRole::OnSecondaryFixed,
            ColorRole::OnSecondaryFixedVariant,
            ColorRole::OnSurface,
            ColorRole::OnSurfaceVariant,
            ColorRole::OnTertiary,
            ColorRole::OnTertiaryContainer,
            ColorRole::OnTertiaryFixed,
            ColorRole::OnTertiaryFixedVariant,
            ColorRole::Outline,
            ColorRole::OutlineVariant,
            ColorRole::Primary,
            ColorRole::PrimaryContainer,
            ColorRole::PrimaryFixed,
            ColorRole::PrimaryFixedDim,
            ColorRole::Scrim,
            ColorRole::Secondary,
            ColorRole::SecondaryContainer,
            ColorRole::SecondaryFixed,
            ColorRole::SecondaryFixedDim,
            ColorRole::Surface,
            ColorRole::SurfaceBright,
            ColorRole::SurfaceContainer,
            ColorRole::SurfaceContainerHigh,
            ColorRole::SurfaceContainerHighest,
            ColorRole::SurfaceContainerLow,
            ColorRole::SurfaceContainerLowest,
            ColorRole::SurfaceDim,
            ColorRole::SurfaceTint,
            ColorRole::SurfaceVariant,
            ColorRole::Tertiary,
            ColorRole::TertiaryContainer,
            ColorRole::TertiaryFixed,
            ColorRole::TertiaryFixedDim,
        ]
    );
    assert_eq!(
        ShapeRole::ALL,
        [
            ShapeRole::CornerExtraExtraLarge,
            ShapeRole::CornerExtraLarge,
            ShapeRole::CornerExtraLargeIncreased,
            ShapeRole::CornerExtraLargeTop,
            ShapeRole::CornerExtraSmall,
            ShapeRole::CornerExtraSmallTop,
            ShapeRole::CornerFull,
            ShapeRole::CornerLarge,
            ShapeRole::CornerLargeEnd,
            ShapeRole::CornerLargeIncreased,
            ShapeRole::CornerLargeStart,
            ShapeRole::CornerLargeTop,
            ShapeRole::CornerMedium,
            ShapeRole::CornerNone,
            ShapeRole::CornerSmall,
        ]
    );
    assert_eq!(
        CornerValueRole::ALL,
        [
            CornerValueRole::CornerValueExtraExtraLarge,
            CornerValueRole::CornerValueExtraLarge,
            CornerValueRole::CornerValueExtraLargeIncreased,
            CornerValueRole::CornerValueExtraSmall,
            CornerValueRole::CornerValueLarge,
            CornerValueRole::CornerValueLargeIncreased,
            CornerValueRole::CornerValueMedium,
            CornerValueRole::CornerValueNone,
            CornerValueRole::CornerValueSmall,
        ]
    );
    assert_eq!(
        ElevationRole::ALL,
        [
            ElevationRole::Level0,
            ElevationRole::Level1,
            ElevationRole::Level2,
            ElevationRole::Level3,
            ElevationRole::Level4,
            ElevationRole::Level5,
        ]
    );
    assert_eq!(
        StateRole::ALL,
        [
            StateRole::Dragged,
            StateRole::Focus,
            StateRole::Hover,
            StateRole::Pressed
        ]
    );
    assert_eq!(
        MotionScheme::ALL,
        [MotionScheme::Standard, MotionScheme::Expressive]
    );
    assert_eq!(
        MotionRole::ALL,
        [
            MotionRole::DefaultSpatial,
            MotionRole::FastSpatial,
            MotionRole::SlowSpatial,
            MotionRole::DefaultEffects,
            MotionRole::FastEffects,
            MotionRole::SlowEffects,
        ]
    );
}
